BB="https://www.epa.gov/bedbugs"; CDCC="https://www.cdc.gov/hygiene/about/when-and-how-to-clean-and-disinfect-a-facility.html"; EPA_L="https://www.epa.gov/pesticide-registration/selected-epa-registered-disinfectants"
add(RA,"role",[
("bedbugs","med","What are signs of bed bugs when stripping a bed?","¿Qué señales de chinches ves al quitar la cama?",["Small dark spots, shed skins, or tiny live bugs on seams","White powder","Big holes","A sweet smell only"],["Puntitos oscuros, mudas o bichitos en las costuras","Polvo blanco","Hoyos grandes","Solo olor dulce"],"EPA: look for dark spots, eggs, shed skins and live bugs on mattress seams.","EPA: busca manchitas, huevos, mudas y bichos en costuras.",BB),
("bedbugs","easy","You think you see bed bugs. What do you do?","Crees ver chinches. ¿Qué haces?",["Stop, don't move linen to other rooms, and tell your supervisor","Keep cleaning","Spray anything you have","Take the linen to the next room"],["Parar, no mover la ropa a otros cuartos y avisar al supervisor","Seguir limpiando","Rociar lo que tengas","Llevar la ropa al siguiente cuarto"],"Containing the room prevents spreading; professionals treat it.","Aislar el cuarto evita que se propague; tratan profesionales.",BB),
("disinfect","med","What's 'dwell time' on a disinfectant label?","¿Qué es el 'tiempo de contacto' en la etiqueta del desinfectante?",["How long the surface must stay wet to kill germs","How long it lasts in the bottle","Drying time of the floor","Time to smell"],["Cuánto debe quedarse mojada la superficie para matar gérmenes","Cuánto dura en la botella","Tiempo de secado del piso","Tiempo del olor"],"EPA/CDC: follow label contact time.","EPA/CDC: sigue el tiempo de contacto.",EPA_L),
("disinfect","easy","Clean first, then disinfect. Why?","Primero limpiar y luego desinfectar. ¿Por qué?",["Dirt blocks disinfectant from working","It's faster the other way","No reason","Disinfectant cleans dirt"],["La suciedad impide que el desinfectante funcione","Al revés es más rápido","Por nada","El desinfectante limpia"],"CDC: cleaning removes soil so disinfecting works.","CDC: limpiar quita suciedad para que desinfectar funcione.",CDCC),
("disinfect","med","Which surfaces are 'high-touch' in a guest room?","¿Cuáles son superficies de mucho contacto en un cuarto?",["Remote, light switches, door handles, phone, faucet","Ceiling","Behind the dresser","Window glass top"],["Control, apagadores, manijas, teléfono, llave del agua","Techo","Detrás del mueble","Parte alta de la ventana"],"CDC: prioritize high-touch surfaces.","CDC: prioriza superficies de mucho contacto.",CDCC),
("cloths","easy","Why use color-coded cloths (e.g., one color for toilets)?","¿Por qué usar trapos de colores (uno para el baño)?",["So toilet cloths never touch glasses, sinks or counters","They look nice","To use fewer","No reason"],["Para que el trapo del baño nunca toque vasos, lavabos ni mostradores","Se ven bonitos","Para usar menos","Por nada"],"Color-coding prevents cross-contamination.","Los colores evitan contaminación cruzada.",CDCC),
("glasses","med","How should drinking glasses be handled in a room?","¿Cómo se manejan los vasos del cuarto?",["Replace with clean, sanitized ones from the supply area — never wash in the bathroom sink","Rinse in the bathroom sink","Wipe with the towel","Leave as is"],["Cambiarlos por limpios y sanitizados del almacén; nunca lavarlos en el lavabo","Enjuagar en el lavabo","Secar con la toalla","Dejarlos igual"],"Glasses washed in-room are a known health risk.","Lavar vasos en el cuarto es riesgo de salud.",CDCC),
("order","easy","What order makes cleaning a room efficient?","¿Qué orden hace eficiente limpiar un cuarto?",["Top to bottom, dry to wet, back to front","Floor first","Random","Bathroom last only"],["De arriba a abajo, seco a mojado, de atrás hacia la puerta","Primero el piso","Al azar","Solo el baño al final"],"Dust falls down; finish at the door.","El polvo cae; terminas en la puerta.",BP),
("dnd","med","A room has had 'Do Not Disturb' for days. What's right?","Un cuarto tiene 'No molestar' desde hace días. ¿Qué es lo correcto?",["Report it to your supervisor for a welfare check per policy","Ignore it forever","Knock and enter","Slide a note and leave it"],["Reportarlo al supervisor para revisión de bienestar según la política","Ignorarlo","Tocar y entrar","Dejar nota y ya"],"Long DND can mean a guest in trouble; policy sets when to check.","Un 'No molestar' largo puede significar un problema.",BP),
("entry","easy","How do you enter an occupied room?","¿Cómo entras a un cuarto ocupado?",["Knock, announce 'Housekeeping', wait, repeat, then enter slowly","Walk right in","Knock once and enter","Use the phone first only"],["Tocar, decir 'Housekeeping', esperar, repetir y entrar despacio","Entrar directo","Tocar una vez y entrar","Solo llamar"],"Standard knock-and-announce protects privacy.","Tocar y anunciar protege la privacidad.",BP),
("entry","med","You enter and the guest is inside. What do you do?","Entras y el huésped está adentro. ¿Qué haces?",["Apologize, offer to come back later, and leave","Clean around them","Ask them to leave","Start the bathroom"],["Disculparte, ofrecer volver y salir","Limpiar a su alrededor","Pedirle que salga","Empezar el baño"],"Respect privacy; return at their preferred time.","Respeta la privacidad; vuelve cuando quiera.",BP),
("cart","easy","Where should your cart be while you clean a room?","¿Dónde va tu carro mientras limpias?",["Blocking the open door, with supplies facing the room","Down the hall","Inside the bathroom","At the elevator"],["Tapando la puerta abierta, con suministros hacia el cuarto","Al fondo del pasillo","En el baño","En el elevador"],"The cart secures the door and your supplies.","El carro protege la puerta y tus cosas.",BP),
("cart","med","What should never be left unattended on your cart?","¿Qué nunca se deja solo en el carro?",["Master keys and chemicals","Toilet paper","Clean towels","Notepad"],["Llaves maestras y químicos","Papel de baño","Toallas limpias","Libreta"],"Keys and chemicals are security and safety risks.","Las llaves y químicos son riesgo.",HAZ),
("inspection","med","What do inspectors most often find missed?","¿Qué es lo que más se pasa en las inspecciones?",["Hair in the bathroom, dust on tops, and items under the bed","Ceiling paint","Window frames outside","The hallway"],["Cabellos en el baño, polvo arriba y cosas bajo la cama","Pintura del techo","Marcos exteriores","El pasillo"],"Focus spots for a guest-ready room.","Puntos clave para un cuarto listo.",BP),
("amenities","easy","A guest asks for more coffee and towels. You're busy. Best answer?","Un huésped pide café y toallas. Estás ocupada. ¿Mejor respuesta?",["Get them now or tell the desk/houseman right away","Say no","Tell them tomorrow","Ignore"],["Llevarlos ahora o avisar a recepción o al houseman","Decir que no","Decir que mañana","Ignorar"],"Quick follow-through earns trust.","Cumplir rápido gana confianza.",BP),
("maintenance","easy","You see a dripping faucet in a room. What do you do?","Ves una llave goteando. ¿Qué haces?",["Report it in the maintenance log or to your supervisor","Ignore it","Fix it with tape","Turn off the water main"],["Reportarlo en la bitácora o al supervisor","Ignorarlo","Ponerle cinta","Cerrar la llave general"],"Small issues become bigger if not reported.","Lo pequeño crece si no se reporta.",BP),
("mold","med","You find black spots on the bathroom caulk. What do you do?","Ves manchas negras en el sellador del baño. ¿Qué haces?",["Clean per procedure and report if it returns so maintenance can recaulk","Paint over it","Ignore it","Use bleach and ammonia"],["Limpiar según el procedimiento y reportar si regresa para resellar","Pintarle encima","Ignorarlo","Mezclar cloro y amoníaco"],"EPA: clean mold and fix moisture; never mix chemicals.","EPA: limpia el moho y arregla la humedad; nunca mezcles químicos.","https://www.epa.gov/mold"),
("checkout","easy","On a checkout, what should you check before stripping the bed?","En una salida, ¿qué revisas antes de quitar la cama?",["For guest items left behind","For the TV channels","Nothing","The window locks only"],["Si el huésped dejó cosas","Los canales","Nada","Solo seguros"],"Check drawers, safe, bathroom and bedding for items.","Revisa cajones, caja fuerte, baño y cama.",BP),
("safe","med","The in-room safe is locked on a checkout. What do you do?","La caja fuerte está cerrada en una salida. ¿Qué haces?",["Report it to the supervisor/front desk — don't try to open it","Force it","Leave it","Ask a guest"],["Reportarlo al supervisor o recepción; no intentes abrirla","Forzarla","Dejarla","Preguntar a un huésped"],"Locked safes may hold guest valuables; follow the opening procedure.","Puede tener valores; se sigue el procedimiento.",BP),
])
add(HM,"role",[
("trash","easy","Where should a full trash bag from the floor go?","¿A dónde va una bolsa de basura llena del piso?",["Straight to the dumpster/trash room — not left in a hallway","Stairwell","Elevator","Behind a door"],["Directo al contenedor o cuarto de basura, no en el pasillo","Escalera","Elevador","Detrás de una puerta"],"Hallways and stairwells must stay clear.","Pasillos y escaleras deben estar libres.",EXIT),
("trash","med","Why not push down on trash with your hand?","¿Por qué no aplastar la basura con la mano?",["Hidden needles or glass can cut you","It's slow","It smells","It breaks the bag"],["Agujas o vidrios escondidos te pueden cortar","Es lento","Huele","Rompe la bolsa"],"OSHA bloodborne pathogens: hidden sharps.","OSHA: punzocortantes escondidos.",BBP),
("vacuum","easy","What should you check before vacuuming the hallway?","¿Qué revisas antes de aspirar el pasillo?",["Cord condition and keep the cord out of walkways","Nothing","Only the color","Bag smell"],["El cable y que no quede en el paso","Nada","Solo el color","El olor"],"Damaged cords shock; loose cords trip.","Un cable dañado da toques; uno suelto hace tropezar.",SLIP),
("vacuum","med","When is a good time to vacuum public hallways?","¿Cuándo conviene aspirar pasillos públicos?",["When guest traffic is low and not early morning near rooms","6 a.m. outside rooms","During check-in rush","Midnight"],["Con poco tráfico y no muy temprano junto a cuartos","6 a. m. fuera de cuartos","En la hora de llegadas","A medianoche"],"Noise and cords affect guests.","El ruido y los cables afectan al huésped.",BP),
("lobby","easy","What's the first impression area you keep spotless?","¿Qué área de primera impresión mantienes impecable?",["Entrance, lobby and public restrooms","Back dock","Boiler room","Roof"],["Entrada, lobby y baños públicos","Muelle","Calderas","Techo"],"Guests judge the hotel in the first minute.","El huésped juzga en el primer minuto.",BP),
("restroom","med","How often should lobby restrooms be checked?","¿Cada cuánto se revisan los baños del lobby?",["Regularly through the shift per the checklist (often hourly)","Once a week","Only on complaints","Never"],["Seguido durante el turno según la lista (a menudo cada hora)","Una vez por semana","Solo con quejas","Nunca"],"A posted check log is standard.","Una bitácora de revisión es lo común.",BP),
("entrance","easy","In winter, what's the main entrance hazard to manage?","En invierno, ¿qué peligro hay en la entrada?",["Wet floors from snow — mats, signs and mopping","Too much sun","Dust","Noise"],["Piso mojado por nieve: tapetes, señales y trapear","Mucho sol","Polvo","Ruido"],"OSHA winter slip prevention.","OSHA prevención de resbalones en invierno.",SLIP),
("ice_melt","med","Why not overuse ice melt on the sidewalk?","¿Por qué no usar demasiada sal en la banqueta?",["It damages concrete and plants and gets tracked inside — use the right amount","It works better","It's free","It warms the floor"],["Daña concreto y plantas y se mete al hotel; usa lo justo","Funciona mejor","Es gratis","Calienta el piso"],"MPCA Smart Salting: more salt isn't more melting.","MPCA: más sal no derrite más.","https://www.pca.state.mn.us/business-with-us/smart-salting-training"),
("ice_melt","hard","Rock salt (sodium chloride) stops working well below about what temperature?","La sal común deja de funcionar bien debajo de qué temperatura?",["About 15°F","About 60°F","About 32°F","About −40°F"],["Unos 15°F","Unos 60°F","Unos 32°F","Unos −40°F"],"MPCA: sodium chloride is less effective below about 15°F.","MPCA: el cloruro de sodio funciona menos debajo de 15°F.","https://www.pca.state.mn.us/business-with-us/smart-salting-training"),
("pool","med","You find a guest's glass bottle on the pool deck. Why remove it?","Hay una botella de vidrio en la alberca. ¿Por qué quitarla?",["Broken glass near a pool is a serious injury risk","It looks bad only","It's not allowed by the brand only","No reason"],["Un vidrio roto en la alberca es riesgo grave","Solo se ve mal","Solo regla de marca","Por nada"],"Glass is commonly banned around pools.","El vidrio suele prohibirse en albercas.",BP),
("pool","easy","The pool water is cloudy. What do you do?","El agua de la alberca está turbia. ¿Qué haces?",["Report it right away — it may need to close until maintenance checks it","Swim test it","Add soap","Ignore"],["Reportarlo de inmediato; puede cerrarse hasta que mantenimiento revise","Probarla nadando","Echar jabón","Ignorar"],"MDH: if you can't see the main drain, the pool must close.","MDH: si no se ve el desagüe, la alberca se cierra.","https://www.health.state.mn.us/communities/environment/pools/"),
("deliveries","easy","A guest asks for a rollaway bed. What's your job?","Un huésped pide cama extra. ¿Qué haces?",["Bring it promptly, made up, and log it","Tell them no","Leave it in the hall","Make the guest pick it up"],["Llevarla pronto, tendida, y registrarla","Decir que no","Dejarla en el pasillo","Que la recoja él"],"Logged deliveries are tracked for pickup.","Se registra para recogerla después.",BP),
("deliveries","med","You deliver to a room. How long should you wait at the door?","Entregas algo a un cuarto. ¿Cuánto esperas en la puerta?",["Knock, announce, step back, and never enter unless invited","Walk in","Leave it on the floor without knocking","Shout"],["Tocar, anunciar, retroceder y no entrar si no te invitan","Entrar","Dejarlo sin tocar","Gritar"],"Respect privacy and safety.","Respeta privacidad y seguridad.",BP),
("stock","easy","Why keep floor closets stocked by the end of shift?","¿Por qué dejar surtidos los cuartos de servicio al final del turno?",["So the next shift and room attendants aren't waiting","It looks nice","It's optional","To hide items"],["Para que el siguiente turno no espere","Se ve bonito","Es opcional","Para esconder"],"Stocking keeps housekeeping moving.","Surtir mantiene el ritmo.",BP),
("chemicals","med","You need to refill a spray bottle. What's required?","Rellenas una botella. ¿Qué se requiere?",["Use the correct chemical and keep the bottle labeled","Any bottle","A water bottle","No label needed"],["Usar el químico correcto y que esté etiquetada","Cualquier botella","Una de agua","Sin etiqueta"],"OSHA HazCom: secondary containers must be labeled.","HazCom: los envases secundarios se etiquetan.",HAZ),
("elevator","easy","An elevator door is not closing right. What do you do?","Una puerta de elevador no cierra bien. ¿Qué haces?",["Report it right away; don't force it","Kick it","Hold it with a cart","Ignore"],["Reportarlo de inmediato; no forzarla","Patearla","Detenerla con un carro","Ignorar"],"Elevators are serviced by licensed techs.","Los elevadores los atienden técnicos.",BP),
("odor","med","A guest reports smoke smell from another room. What do you do?","Un huésped reporta olor a humo de otro cuarto. ¿Qué haces?",["Tell the front desk/manager right away so it can be checked","Ignore","Spray air freshener in the hall","Knock and yell"],["Avisar a recepción o gerente de inmediato para revisar","Ignorar","Echar aromatizante","Tocar y gritar"],"Could be smoking or a fire — check fast.","Puede ser alguien fumando o un incendio.",FIRE),
])
